  $$('[data-p]',el).forEach(function(b){b.onclick=function(){$$('[data-p]',el).forEach(function(x){x.setAttribute('aria-pressed',x===b)});E.sfx.tick();E.toast('سُجّل التوقع. لننفّذ التجربة!')}});
