  el.innerHTML='<div class="eyebrow">المحطة ٣ · خصائص المادة ص ١٠٦ · تجربة توضيحية</div><h1 class="t" style="font-size:42px">مختبر الميزان: هل للهواء كتلة؟</h1><div class="row grow" style="min-height:0"><div class="col" style="flex:1.45;gap:8px"><canvas class="sim lab" id="amc" width="1000" height="560" style="height:100%;min-height:0;flex:1"></canvas><div id="amt"></div></div>'+
   '<div class="col grow side" style="gap:12px"><div id="amtb"></div>'+
   '<div class="card" style="padding:14px 18px"><h3>خطوات التجربة</h3><p style="margin:0;font-size:19px;line-height:1.7">علّقنا بالونين متماثلين على طرفي ميزان ذي كفّتين. انفخ أحد البالونين بالهواء، ولاحظ ماذا يحدث للميزان، ثم انفخ الآخر.</p></div>'+
   '<div class="card reveal" id="amEx" style="padding:14px 18px"><h3>الاستنتاج</h3><div class="explain">مال الميزان نحو البالون المملوء بالهواء؛ فالهواء <b>له كتلة</b>، وانتفاخ البالون دليل على أنه <b>يشغل حيزًا</b>. فالهواء مادة؛ لأنه مكوّن من عناصر مثل الهيدروجين والأكسجين والكربون والنيتروجين. أما الضوء فليس مادة؛ لأنه ليس له كتلة ولا يشغل حيزًا.</div></div><div id="amq"></div></div></div>';
  var c=$('#amc',el),x=c.getContext('2d'),f=[0,0],tf=[0,0],a=0,run=false,raf=0;
