    var px=500,py=130,L=330;x.save();x.translate(px,py);x.rotate(a);x.fillStyle='#c79a3a';LK.rr(x,-L,-9,2*L,18,9);x.fill();x.strokeStyle='#7a5a12';x.lineWidth=2;x.stroke();
