    x.fillStyle='#2d3a40';x.beginPath();x.arc(px,py,16,0,7);x.fill();x.fillStyle='#ffc23d';x.beginPath();x.arc(px,py,6,0,7);x.fill();
    /* مؤشر */x.save();x.translate(px,py);x.rotate(a);x.strokeStyle='#d9453b';x.lineWidth=5;x.beginPath();x.moveTo(0,0);x.lineTo(0,110);x.stroke();x.restore();
    x.strokeStyle='#2d3a40';x.lineWidth=3;x.beginPath();x.arc(px,py,110,Math.PI/2-.35,Math.PI/2+.35);x.stroke();x.beginPath();x.moveTo(px,py+102);x.lineTo(px,py+120);x.stroke();
    [-1,1].forEach(function(s,i){var hx=px+Math.cos(a)*s*(L-14),hy=py+Math.sin(a)*s*(L-14);x.strokeStyle='#4f6f7c';x.lineWidth=2;x.beginPath();x.moveTo(hx,hy);x.lineTo(hx,hy+60);x.stroke();balloon(x,hx,hy+60,f[i],i?'#ff6b6b':'#4aa3ff',i?'#b42318':'#1f5fd0')});
