  LK.tools($('#amt',el),[['🎈','انفخ البالون الأحمر'],['🎈','انفخ البالون الأزرق'],['💨','أفرغ البالونين']],function(i){if(i===2)tf=[0,0];else tf[i===0?1:0]=1;E.sfx.whoosh()});
