  var cv=$('#rc',el),x=cv.getContext('2d'),W=1100,H=600,FX=640,FY=300,RING=250;var P=[],hits=[],C=[0,0,0],mode='r',stream=false,zoom=0,raf=0,run=false,queue=0;
