    /* المصدر */
    x.fillStyle='#4a5670';x.fillRect(40,FY-40,70,80);x.fillStyle='#ffcc4d';x.fillRect(106,FY-10,10,20);x.font='600 17px "IBM Plex Sans Arabic"';x.fillStyle='#a9bddf';x.textAlign='center';x.fillText('مصدر جسيمات ألفا',95,FY-52);
    /* صفيحة الذهب */
    var gg=x.createLinearGradient(FX-6,0,FX+6,0);gg.addColorStop(0,'#b88a1f');gg.addColorStop(.5,'#ffe29a');gg.addColorStop(1,'#b88a1f');x.fillStyle=gg;x.fillRect(FX-5,FY-150,10,300);x.fillStyle='#f5c451';x.fillText('صفيحة ذهب رقيقة',FX,FY-162);x.font='700 18px "Readex Pro"';x.fillStyle='#7dffb0';x.fillText('شاشة فلورسنتية تتوهج عند سقوط الجسيمات',FX,FY+RING+32);x.font='600 15px "IBM Plex Sans Arabic"';[['150,255,170','نفذت'],['255,214,70','انحرفت'],['255,90,90','ارتدّت']].forEach(function(l,i){x.fillStyle='rgb('+l[0]+')';x.beginPath();x.arc(60+i*110,H-26,8,0,7);x.fill();x.fillStyle='#dfe8ff';x.textAlign='left';x.fillText(l[1],74+i*110,H-21)});x.textAlign='center';
    /* الجسيمات */
