    var t=performance.now()/1000;for(var i=0;i<6;i++){var u=(t*.35+i/6)%1;var yy=zy-90+i*36;var px=zx-R+u*R*2;if(Math.hypot(px-zx,yy-zy)<R){x.fillStyle='#ff8a5c';x.beginPath();x.arc(px,yy,3,0,7);x.fill()}}
