(function(){var k=0;L1.stations.forEach(function(st){if(['intro','wonder','prior','glass','fold','goals'].indexOf(st.id)>=0)return;k++;var base=st.name.replace(/^م\S*\s+/,'');st.name='م'+n(k)+' '+base;var kk=k,b=st.build;st.build=function(el,ctx){var r=b(el,ctx);var ey=$('.eyebrow',el);if(ey&&ey.firstChild&&ey.firstChild.nodeType===3)ey.firstChild.textContent=ey.firstChild.textContent.replace(/^المحطة\s*[٠-٩]*/,'المحطة '+n(kk));return r}})})();
